#include "Core/Track.h"
#include <algorithm>
namespace myvocal { Track::Track(int id):m_id(id){m_name=QStringLiteral("Track %1").arg(id+1);} int Track::id()const noexcept{return m_id;} const QString&Track::name()const noexcept{return m_name;} void Track::setName(const QString&v){m_name=v;} bool Track::muted()const noexcept{return m_muted;} void Track::setMuted(bool v){m_muted=v;} bool Track::solo()const noexcept{return m_solo;} void Track::setSolo(bool v){m_solo=v;} double Track::volume()const noexcept{return m_volume;} void Track::setVolume(double v){m_volume=std::clamp(v,0.0,2.0);} double Track::pan()const noexcept{return m_pan;} void Track::setPan(double v){m_pan=std::clamp(v,-1.0,1.0);} const QString&Track::singerPath()const noexcept{return m_singerPath;} void Track::setSingerPath(const QString&v){m_singerPath=v;} const QString&Track::phonemizer()const noexcept{return m_phonemizer;} void Track::setPhonemizer(const QString&v){m_phonemizer=v;} QVector<Note>&Track::notes()noexcept{return m_notes;} const QVector<Note>&Track::notes()const noexcept{return m_notes;} qint64 Track::addNote(Note n){m_notes.push_back(std::move(n));return m_notes.back().getId();} bool Track::removeNoteById(qint64 id,Note*removed){for(int i=0;i<m_notes.size();++i)if(m_notes[i].getId()==id){if(removed)*removed=m_notes[i];m_notes.removeAt(i);return true;}return false;} Note*Track::findNote(qint64 id){for(auto&n:m_notes)if(n.getId()==id)return &n;return nullptr;} const Note*Track::findNote(qint64 id)const{for(const auto&n:m_notes)if(n.getId()==id)return &n;return nullptr;} }
